 const mediaError=p=>Promise.resolve(p).catch(error=>toast(error.message||'The media action could not be completed.'));
 const intercepted=new Set(['mic','cam','screen','hand','wave','zoom','map','hall-booth','map-destination','hall-help','project-filter','event-filter','chat-scope','enter-hall','publish']);
