  if(e.target.id==='project-csv'){
   const file=e.target.files?.[0];if(!file)return;
   try{const rows=parseCSV(await file.text());const headers=rows.shift()?.map(s=>s.trim().toLowerCase())||[];if(!['title','category','members','emails','abstract'].every(h=>headers.includes(h)))throw new Error('CSV needs title, category, members, emails and abstract columns.');const imported=rows.filter(r=>r.some(Boolean)).map(row=>Object.fromEntries(headers.map((key,i)=>[key,row[i]||''])));if(imported.some(r=>!r.title||!r.emails))throw new Error('Every project needs a title and member emails.');f.submissions.push(...imported);persist();$('#csv-preview').innerHTML=`<div class="info-note">${icon('check')}${imported.length} projects imported. ${Math.ceil(f.submissions.length/5)} hall assignments planned.</div>`;toast('CSV imported into the local preview. Reopen this page to see all rows.');}catch(error){toast(error.message);}
  }
