 function parseCSV(text){const rows=[[]];let field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){rows.at(-1).push(field);field='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;rows.at(-1).push(field);rows.push([]);field='';}else field+=c;}if(quoted)throw new Error('A quoted CSV field is not closed.');rows.at(-1).push(field);return rows;}
